import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    state = {"record_start": True}

    def lines():
        for line in io.StringIO(raw_csv, newline=""):
            if state["record_start"] and line.lstrip().startswith("#"):
                continue
            state["record_start"] = False
            yield line

    reader = csv.reader(lines(), delimiter=";", quotechar='"', strict=False)
    records = []
    old_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2**31 - 1)
        while True:
            state["record_start"] = True
            try:
                row = next(reader)
            except StopIteration:
                break
            if not records and not row:
                continue
            records.append(row if row else [""])
    finally:
        csv.field_size_limit(old_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])
    used = set(columns)
    number = 1
    while len(columns) < width:
        name = "extra_" + str(number)
        number += 1
        if name not in used:
            columns.append(name)
            used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
